-- AI ministry-fit summary (capstone). One row per person (upsert on person_id).
-- UNLIKE the assessment tables, this row is MACHINE-GENERATED server-side by the
-- /api/ministry-fit route (service-role, bypasses RLS). It is auto-generated once a
-- person has completed all three Equip assessments (spiritual gifts + big five +
-- passion) and is SHARED with both the person AND their coach — so authenticated
-- users get SELECT only (person + admin + downline/coach); all writes go through
-- the service-role route. `inputs_hash` fingerprints the three assessment inputs
-- used, so the route can skip regeneration until an assessment actually changes.

create table if not exists public.ministry_fit_results (
  id             uuid primary key default gen_random_uuid(),
  person_id      uuid not null references public.people(id) on delete cascade,
  summary        text not null default '',
  suggestions    jsonb not null default '[]'::jsonb,  -- [{ ministry, rationale, fitScore }]
  inputs_hash    text,                                 -- fingerprint of the 3 assessment inputs
  model          text,                                 -- provenance, e.g. 'claude-sonnet-5'
  generated_at   timestamptz not null default now(),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create unique index if not exists ministry_fit_results_person_id_key
  on public.ministry_fit_results (person_id);

comment on table public.ministry_fit_results is
  'Latest AI ministry-fit summary per person (capstone). Machine-generated server-side from the three Equip assessments. One row per person. Shared read: person + admin + coach downline.';

-- ── updated_at trigger ────────────────────────────────────────────────────────
create or replace function public.set_ministry_fit_results_audit()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  return new;
end; $$;

drop trigger if exists trg_ministry_fit_results_audit on public.ministry_fit_results;
create trigger trg_ministry_fit_results_audit
  before insert or update on public.ministry_fit_results
  for each row execute function public.set_ministry_fit_results_audit();

-- ── RLS ───────────────────────────────────────────────────────────────────────
-- Authenticated users may only READ (never write) — the summary is generated by the
-- service-role route, which bypasses RLS. Same shared-read shape as the assessment
-- tables: owner, admin, or anyone whose downline includes this person (the coach).
alter table public.ministry_fit_results enable row level security;

drop policy if exists ministry_fit_results_select on public.ministry_fit_results;
create policy ministry_fit_results_select on public.ministry_fit_results
for select to authenticated using (
  person_id = public.current_person_id()
  or public.current_person_is_admin()
  or person_id in (select public.my_downline_ids())
);

grant select on public.ministry_fit_results to authenticated;
